StructuredTextModel.Text:
(*
				CALIBRATE ALPHA FUNCTION BLOCK
				Fits upstream loss α from measured (Q, Ps) test point
				
				Author: AhmadMohammad
				
				REVISIONS:
				V1.0.0		-		2025-11-05		-		AM		-		Initial implementation
				
				ERROR IDs:
				1001		-		Invalid fluid selection
				1002		-		Invalid nozzle selection
				1003		-		Flow too low (< 0.1 L/min)
*)

// - - - - - - - - - - - - - - - - - - - - INPUT EDGE DETECTION
Execute_RE(Clk:=Execute);
Execute_FE(Clk:=Execute);

// - - - - - - - - - - - - - - - - - - - - START AND STOP OF FB
IF Execute_RE.Q AND NOT Busy THEN
  Busy:=TRUE;
  fbStep:=10;
END_IF;

IF Execute_FE.Q AND Busy THEN
  fbStep:=800;
ELSIF Execute_FE.Q AND NOT Busy THEN
  fbStep:=900;
END_IF;

// - - - - - - - - - - - - - - - - - - - - MAIN CODE CASE
CASE fbStep OF 
  
  // - - - - - - -   CASE 000: IDLE   - - - - - - - //
  0: // idle
    fbStep:=0;
  
  // - - - - - - -   CASE 010: INITIALISE   - - - - - - - //
  10: // initialise calibration
    ErrorID:=0;
    Done:=FALSE;
    Error:=FALSE;
    fbStep:=20;
  
  // - - - - - - -   CASE 020: VALIDATE INPUTS   - - - - - - - //
  20: // validate fluid
    IF iFluid < 0 OR iFluid > 2 THEN
      Error:=TRUE;
      ErrorID:=1001;
      fbStep:=800;
    ELSE
      fbStep:=30;
    END_IF;
  
  // - - - - - - -   CASE 030: VALIDATE NOZZLE   - - - - - - - //
  30: // validate nozzle
    IF iNozzle < 0 OR iNozzle > 5 THEN
      Error:=TRUE;
      ErrorID:=1002;
      fbStep:=800;
    ELSE
      fbStep:=40;
    END_IF;
  
  // - - - - - - -   CASE 040: GET BETA AND CHECK FLOW   - - - - - - - //
  40: // get beta constant and check flow
    rBeta := GetBeta(iFluid, iNozzle);
    rQ_squared := rQ_measured * rQ_measured;
    
    IF rQ_squared > 0.01 THEN
      fbStep:=50;
    ELSE
      Error:=TRUE;
      ErrorID:=1003;
      fbStep:=800;
    END_IF;
  
  // - - - - - - -   CASE 050: CALCULATE ALPHA   - - - - - - - //
  50: // calculate alpha = (Ps / Q²) - β
    rAlpha_new := (rPs_measured / rQ_squared) - rBeta;
    
    IF rAlpha_new < 0.0 THEN
      rAlpha_new := 0.0;
    END_IF;
    IF rAlpha_new > 100.0 THEN
      rAlpha_new := 100.0;
    END_IF;
    
    fbStep:=60;
  
  // - - - - - - -   CASE 060: STORE ALPHA   - - - - - - - //
  60: // store alpha in global variable
    CASE iFluid OF
      0: rAlpha_Water := rAlpha_new;
      1: rAlpha_ISOXEL := rAlpha_new;
      2: rAlpha_DFAB := rAlpha_new;
    END_CASE;
    
    Done:=TRUE;
    fbStep:=800;
  
  // - - - - - - -   CASE 800: STOP FB   - - - - - - - //
  800: // stop and prep for reset
    fbStep:=900;
  
  // - - - - - - -   CASE 900: RESET FB   - - - - - - - //
  900: // clear and prepare for next execution
    Busy:=FALSE;
    
ELSE
  Error:=TRUE;
  ErrorID:=99000;
  
END_CASE;

// - - - - - - - - - - - - - - - - - - - - CLEAR BUSY FLAG
IF Error THEN
  Busy:=FALSE;
END_IF;

// - - - - - - - - - - - - - - - - - - - - FB StateID
StateID:=fbStep;
